// right-to-left interface languages
export const isRTL = (lang) => lang === "ar" || lang === "fa";

export const LangContext = createContext("uk");
export const useLang = () => useContext(LangContext);

export function makeT(lang) {
  return (key, vars) => {
    let s = STR[lang]?.[key] ?? STR.uk[key] ?? key;
    if (typeof s === "string" && vars)
      for (const k in vars) s = s.replaceAll(`{${k}}`, vars[k]);
    return s;
  };
}
export function useT() {
  return makeT(useLang());
}

export const moduleSub = (lang, m) =>
  lang === "uk" ? m.titleUk
    : lang in LX ? MODULE_SUBS[m.id]?.[LX[lang]] ?? m.titleUk
    : MORE_MODULE_SUBS[lang]?.[m.id] ?? m.titleUk;
export const levelSub = (lang, l) =>
  lang === "uk" ? l.titleUk
    : lang in LX ? LEVEL_SUBS[l.id]?.[LX[lang]] ?? l.titleUk
    : MORE_LEVEL_SUBS[lang]?.[l.id] ?? l.titleUk;
export const levelBlurb = (lang, l) =>
  lang === "uk" ? l.blurb
    : lang in LX ? LEVEL_BLURBS[l.id]?.[LX[lang]] ?? l.blurb
    : MORE_LEVEL_BLURBS[lang]?.[l.id] ?? l.blurb;

// index into the compact [ru,en,tr,de,hi] arrays; newer languages
// (pl, es, fr, ro, it) live in the MORE_* per-language maps below
